export const productionOrganizationOptimizationGlossary: TextLectureCourse["glossary"] = [
  { term: "Затраты", definition: "Денежная оценка ресурсов, использованных или предназначенных для определённой деятельности, изделия, заказа или периода." },
  { term: "Объект затрат", definition: "То, для чего отдельно измеряют затраты: продукция, заказ, партия, операция, станок, подразделение или проект." },
  { term: "Выплата", definition: "Фактическое движение денежных средств; её момент может не совпадать с моментом потребления ресурса и признания расхода." },
  { term: "Расход", definition: "Признанное за период уменьшение экономической выгоды по установленным правилам учёта." },
  { term: "Прямые затраты", definition: "Затраты, которые можно экономически обоснованно отнести к конкретному объекту без косвенного распределения." },
  { term: "Косвенные затраты", definition: "Общие для нескольких объектов затраты, распределяемые между ними по выбранной базе." },
  { term: "Переменные затраты", definition: "Затраты, величина которых в рассматриваемом диапазоне меняется при изменении объёма деятельности." },
  { term: "Постоянные затраты", definition: "Затраты, которые в пределах определённого периода и диапазона мощности не зависят непосредственно от объёма выпуска." },
  { term: "Релевантные затраты", definition: "Будущие затраты, которые различаются между рассматриваемыми вариантами и поэтому влияют на решение." },
  { term: "Упущенная выгода", definition: "Ценность лучшей отвергнутой альтернативы при выборе одного способа использования ограниченного ресурса." },
  { term: "Амортизация", definition: "Систематическое перенесение стоимости долгосрочного актива на периоды или продукцию по мере использования его ресурса." },
  { term: "Себестоимость", definition: "Денежная оценка затрат, отнесённых к изготовлению и, в зависимости от состава, реализации продукции." },
  { term: "Производственная себестоимость", definition: "Себестоимость в составе затрат, связанных с изготовлением продукции и обслуживанием производства." },
  { term: "Полная себестоимость", definition: "Себестоимость, дополненная относимыми расходами на управление, продажу и другие предусмотренные расчётом элементы." },
  { term: "Калькуляция", definition: "Расчёт себестоимости конкретного объекта по статьям затрат и установленным правилам отнесения." },
  { term: "База распределения", definition: "Измеримый показатель, пропорционально которому косвенные затраты относят к объектам, например машино-часы." },
  { term: "Плановая себестоимость", definition: "Ожидаемая себестоимость, рассчитанная для будущего периода по плановым нормам, ценам и объёму." },
  { term: "Фактическая себестоимость", definition: "Себестоимость, полученная по реально признанным затратам и фактическому объёму годной продукции." },
  { term: "Выручка", definition: "Доход от реализации продукции, работ или услуг до вычитания относимых расходов." },
  { term: "Прибыль", definition: "Абсолютное превышение относимых доходов над расходами за определённый период или по объекту." },
  { term: "Рентабельность", definition: "Относительный показатель доходности, в котором прибыль сопоставляется с явно выбранной базой: себестоимостью, выручкой или капиталом." },
  { term: "Результативность", definition: "Степень достижения поставленной цели независимо от того, сколько ресурсов было израсходовано." },
  { term: "Эффективность", definition: "Соотношение полезного результата и использованных ресурсов при соблюдении заданных требований и ограничений." },
  { term: "Удельные затраты", definition: "Количество ресурса или его денежная оценка, приходящиеся на единицу годного результата." },
  { term: "Срок окупаемости", definition: "Период, за который накопленный денежный эффект компенсирует первоначальные инвестиции при принятых допущениях." },
  { term: "Организационная структура", definition: "Устойчивое распределение задач, полномочий, ответственности и связей между ролями и подразделениями." },
  { term: "Подразделение", definition: "Формально выделенная часть организации с определёнными задачами, руководством и ресурсами." },
  { term: "Полномочие", definition: "Признанное право принимать решение, давать обязательное указание или распоряжаться ресурсом в заданных границах." },
  { term: "Ответственность", definition: "Обязанность обеспечить порученный результат и объяснить отклонение от согласованных требований." },
  { term: "Делегирование", definition: "Передача задачи и необходимых полномочий на более низкий уровень при сохранении общей управленческой ответственности." },
  { term: "Норма управляемости", definition: "Число непосредственных подчинённых, работой которых руководитель может результативно управлять в данных условиях." },
  { term: "Вертикальная связь", definition: "Связь между уровнями управления, по которой передаются полномочия, задания, отчётность и эскалация." },
  { term: "Горизонтальная связь", definition: "Координация подразделений или ролей одного уровня для выполнения общей межфункциональной работы." },
  { term: "Централизация", definition: "Сосредоточение значительной части решений и полномочий на верхнем или едином центре управления." },
  { term: "Децентрализация", definition: "Передача части решений ближе к подразделению и месту возникновения оперативной информации." },
  { term: "Линейная структура", definition: "Структура с ясной последовательной вертикалью, где исполнитель имеет одного непосредственного административного руководителя." },
  { term: "Линейно-штабная структура", definition: "Линейная вертикаль, дополненная специалистами, которые анализируют и готовят решения для руководителей." },
  { term: "Функциональная структура", definition: "Группировка людей по профессиональному виду деятельности: производство, технология, качество, финансы и другим функциям." },
  { term: "Дивизиональная структура", definition: "Организация крупных единиц по продукту, рынку, клиенту или территории с комплексной ответственностью за направление." },
  { term: "Проектная структура", definition: "Временное объединение людей и ресурсов под уникальный результат с назначенным руководителем проекта." },
  { term: "Матричная структура", definition: "Сочетание функционального и проектного или продуктового управления с разделёнными линиями полномочий." },
  { term: "Процессная структура", definition: "Организация управления вокруг сквозных процессов и результата для их потребителя." },
  { term: "Владелец процесса", definition: "Роль, отвечающая за результат и развитие сквозного процесса через границы отдельных функций." },
  { term: "Центр компетенций", definition: "Группа специалистов, которая развивает общие профессиональные методы, стандарты и знания для нескольких направлений." },
  { term: "Оптимизация", definition: "Выбор и изменение варианта системы для улучшения заданного критерия при соблюдении ограничений." },
  { term: "Критерий оптимизации", definition: "Показатель или правило сравнения, по которому один допустимый вариант признаётся предпочтительнее другого." },
  { term: "Ограничение задачи оптимизации", definition: "Обязательное условие допустимости варианта, которое нельзя нарушить, например предел бюджета, мощности, срока, качества или безопасности. Не следует путать с системным ограничением, лимитирующим выпуск." },
  { term: "Lean", definition: "Бережливое производство: подход к созданию ценности с меньшими потерями через понимание потока, течение, вытягивание и постоянное совершенствование." },
  { term: "Поток создания ценности", definition: "Полная последовательность материальных и информационных действий для конкретного продукта от потребности до результата." },
  { term: "Непрерывное течение", definition: "Стремление передавать предмет работы между создающими результат действиями без лишних ожиданий, возвратов и накопления партий." },
  { term: "Вытягивание", definition: "Принцип вытягивающей системы: запуск и пополнение по подтверждённой потребности следующего звена в пределах заданного лимита." },
  { term: "Совершенство в Lean", definition: "Непрерывное приближение к созданию требуемой ценности без потерь через повторяющиеся циклы улучшения." },
  { term: "Потеря", definition: "Потребление ресурса, не создающее требуемой ценности и не являющееся неизбежным условием её обеспечения." },
  { term: "Локальная оптимизация", definition: "Улучшение показателя отдельного участка, которое не улучшает или даже ухудшает результат всей системы." },
  { term: "Симптом", definition: "Наблюдаемое проявление проблемы, которое само по себе ещё не объясняет порождающий её механизм." },
  { term: "Коренная причина", definition: "Подтверждённый управляемый механизм, устранение которого предотвращает повторение рассматриваемой проблемы." },
  { term: "Базовая линия", definition: "Численно описанное исходное состояние показателя до изменения, используемое для сравнения эффекта." },
  { term: "Пилот", definition: "Ограниченное внедрение решения для проверки причинного эффекта и рисков до полного тиражирования." },
  { term: "Уравновешивающий показатель", definition: "Показатель, который контролируют, чтобы улучшение основной цели не достигалось ценой неприемлемого ухудшения другой стороны процесса." },
  { term: "DMAIC", definition: "Последовательность Define–Measure–Analyze–Improve–Control для определения проблемы, измерения, анализа, улучшения и контроля." },
  { term: "ECRS", definition: "Логика улучшения Eliminate–Combine–Rearrange–Simplify: исключить, объединить, переставить и упростить действия." },
  { term: "Технологическая операция", definition: "Законченная часть технологического процесса, выполняемая на одном рабочем месте над определённым объектом; в производственном контексте часто кратко называется операцией." },
  { term: "Установ", definition: "Часть операции, выполняемая при одном неизменном закреплении обрабатываемой заготовки." },
  { term: "Технологический переход", definition: "Законченная часть операции с постоянным характером обработки определённых поверхностей и применяемого инструмента." },
  { term: "Рабочий ход", definition: "Часть перехода, при которой инструмент непосредственно изменяет форму, размер, качество поверхности или свойства заготовки." },
  { term: "Технологический маршрут", definition: "Установленная последовательность операций и рабочих мест, по которым проходит изделие или его часть; в контексте технологии часто кратко называется маршрутом." },
  { term: "Структурная оптимизация", definition: "Изменение состава, порядка, зависимостей или распределения элементов процесса для улучшения общего результата." },
  { term: "Параметрическая оптимизация", definition: "Подбор значений параметров внутри сохранённой структуры, например режима резания, партии или числа исполнителей." },
  { term: "Технологическая наследственность", definition: "Влияние свойств и погрешностей, сформированных на ранних операциях, на результат последующих операций." },
  { term: "Предшествование", definition: "Логическое или физическое условие, требующее завершения одной работы до начала другой." },
  { term: "Концентрация операций", definition: "Объединение нескольких переходов или видов обработки в одной операции либо на одном рабочем месте." },
  { term: "Дифференциация операций", definition: "Разделение технологического процесса на более простые специализированные операции." },
  { term: "Транспортная партия", definition: "Количество изделий, одновременно передаваемых с одной операции на следующую; также называется передаточной партией." },
  { term: "Технологическая планировка", definition: "Размещение однотипного оборудования по функциональным участкам, например токарному или шлифовальному." },
  { term: "Предметная планировка", definition: "Размещение разных ресурсов по последовательности обработки конкретного изделия или семейства." },
  { term: "Такт производства", definition: "Доступное производственное время, делённое на потребность клиента за тот же период; также кратко называется тактом." },
  { term: "Балансировка линии", definition: "Распределение содержания работ между позициями для поддержания требуемого ритма при соблюдении зависимостей." },
  { term: "Проект", definition: "Ограниченная во времени деятельность по созданию уникального согласованного результата." },
  { term: "Сетевой график", definition: "Модель работ проекта и логических зависимостей, используемая для расчёта сроков, путей и резервов." },
  { term: "Работа сетевого графика", definition: "Действие или процесс с определённым результатом и длительностью, обычно требующий ресурсов." },
  { term: "Событие сетевого графика", definition: "Момент готовности, который завершает одни и разрешает начало других работ и не имеет собственной длительности." },
  { term: "Фиктивная работа", definition: "Условная работа нулевой длительности и без ресурсов, показывающая только логическую зависимость в сети работ на стрелках." },
  { term: "Путь сетевого графика", definition: "Непрерывная последовательность связанных работ; длительность пути равна сумме их длительностей." },
  { term: "Раннее начало", definition: "Самый ранний момент начала работы после завершения всех обязательных предшественников." },
  { term: "Позднее начало", definition: "Самый поздний допустимый момент начала работы без сдвига принятого срока завершения проекта." },
  { term: "Полный резерв", definition: "Допустимый сдвиг работы без изменения конечного срока проекта при сохранении рассчитанной сети." },
  { term: "Свободный резерв", definition: "Допустимый сдвиг работы без задержки раннего начала её непосредственных последователей." },
  { term: "Выравнивание ресурсов", definition: "Корректировка календаря работ с учётом ограниченной доступности общих исполнителей, оборудования и других ресурсов." },
  { term: "Базовый план", definition: "Утверждённая версия сроков и содержания проекта, относительно которой измеряют фактическое выполнение и изменения." },
  { term: "Модель", definition: "Целенаправленно упрощённое представление системы, сохраняющее свойства, существенные для исследовательского вопроса." },
  { term: "Имитационное моделирование", definition: "Исследование поведения системы во времени с помощью многократного выполнения её компьютерной модели." },
  { term: "Сущность модели", definition: "Индивидуальный объект, который проходит процесс или действует в нём: заказ, деталь, транспорт или работник." },
  { term: "Ресурс модели", definition: "Ограниченная способность выполнять работу, например станок, оператор, кран или измерительная машина." },
  { term: "Очередь модели", definition: "Набор сущностей, ожидающих доступного ресурса, сигнала или выполнения другого условия." },
  { term: "Состояние модели", definition: "Набор переменных, достаточный для описания текущего положения системы и продолжения расчёта." },
  { term: "Событие модели", definition: "Момент, в который дискретно изменяется состояние модели, например завершается обработка или приходит заказ." },
  { term: "Дискретно-событийное моделирование", definition: "Подход, где состояние меняется в отдельные моменты событий, удобный для очередей, маршрутов и ограниченных ресурсов." },
  { term: "Системная динамика", definition: "Подход к моделированию агрегированных накопителей, потоков, обратных связей и задержек во времени." },
  { term: "Накопитель", definition: "Переменная системной динамики, хранящая количество, которое увеличивается и уменьшается входящими и исходящими потоками." },
  { term: "Поток системной динамики", definition: "Скорость изменения накопителя, например выпуск в день, поступление заказов или найм работников." },
  { term: "Обратная связь модели", definition: "Замкнутая причинная цепь, в которой изменение величины через другие элементы в итоге влияет на неё саму." },
  { term: "Агентное моделирование", definition: "Подход, где общее поведение возникает из действий и взаимодействия автономных неоднородных агентов." },
  { term: "Агент", definition: "Автономный объект модели с собственным состоянием, правилами поведения и взаимодействием с окружением." },
  { term: "Метод Монте-Карло", definition: "Многократный расчёт со случайным выбором входов для оценки распределения и вероятностей результата." },
  { term: "Непрерывная модель", definition: "Модель, в которой состояние меняется непрерывно во времени и обычно описывается уравнениями." },
  { term: "Гибридная модель", definition: "Модель, объединяющая несколько парадигм, например дискретные события, непрерывную динамику и агентов." },
  { term: "Случайная величина", definition: "Числовой результат случайного явления с определённым набором возможных значений и вероятностей." },
  { term: "Распределение вероятностей", definition: "Описание возможных значений случайной величины и вероятности или плотности их появления." },
  { term: "Концептуальная модель", definition: "Независимое от программы описание цели, границ, объектов, правил, входов, выходов и допущений модели." },
  { term: "Допущение модели", definition: "Явно принятое упрощение реальности, область применимости и влияние которого должны быть оценены." },
  { term: "Прогрев модели", definition: "Начальный переходный период, исключаемый из статистики, если он вызван искусственными начальными условиями." },
  { term: "Прогон модели", definition: "Одно выполнение модели на установленном временном горизонте и с конкретным набором входов." },
  { term: "Репликация", definition: "Независимое повторение случайного сценария модели для оценки изменчивости и точности результата." },
  { term: "Случайное зерно", definition: "Начальное значение генератора псевдослучайных чисел, позволяющее повторить одну и ту же последовательность." },
  { term: "Верификация модели", definition: "Проверка того, что компьютерная реализация правильно соответствует задуманной концептуальной модели." },
  { term: "Валидация модели", definition: "Проверка достаточного соответствия модели реальной системе для конкретной цели и решения." },
  { term: "Калибровка", definition: "Настройка неопределённых параметров модели по части наблюдаемых данных без подмены независимой валидации." },
  { term: "Маржинальность", definition: "Способность изделия или заказа создавать вклад в покрытие общих затрат и прибыль после учёта связанных с ним переменных затрат." },
  { term: "Стоимость денег во времени", definition: "Принцип, согласно которому одинаковая денежная сумма сегодня и в будущем имеет разную ценность из-за возможной доходности, инфляции и риска." },
  { term: "Медиана", definition: "Серединное значение упорядоченного набора: половина наблюдений не больше него, а половина не меньше; менее чувствительна к редким выбросам, чем среднее." },
  { term: "Репрезентативный период", definition: "Период наблюдения, достаточно хорошо представляющий типичные изделия, смены, сезонность и режимы исследуемого процесса." },
  { term: "Стационарное поведение", definition: "Режим, в котором основные статистические свойства процесса не меняются со временем только из-за начальных условий модели." },
  { term: "Инвариант модели", definition: "Условие, которое обязано сохраняться при любом корректном ходе модели, например баланс поступивших, выпущенных и оставшихся деталей." },
  { term: "Статистическая значимость", definition: "Оценка того, насколько наблюдаемое различие трудно объяснить случайным разбросом при выбранной процедуре и её допущениях; не показывает автоматически практическую выгоду." },
  { term: "Доверительный интервал", definition: "Рассчитанный по выборке диапазон неопределённости оценки параметра при заданной статистической процедуре." },
  { term: "Квантиль", definition: "Значение, ниже которого находится заданная доля наблюдаемого распределения, например 90 процентов сроков." },
  { term: "Анализ чувствительности", definition: "Исследование изменения вывода модели при варьировании входного параметра или допущения." },
  { term: "Робастность", definition: "Устойчивость предпочтительного решения и его результата к правдоподобным изменениям условий и параметров." },
  { term: "Сценарий", definition: "Согласованный набор условий, параметров и правил, описывающий один исследуемый вариант будущего или политики." },
  { term: "План эксперимента", definition: "Заранее установленная схема изменения факторов, числа повторений и анализа результатов для обоснованного сравнения вариантов." },
];
